<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue';
import { api, type SupportTicketResult } from '../api/client.js';

const enabled=ref<boolean|null>(null);const loadingStatus=ref(true);const submitting=ref(false);const error=ref('');const result=ref<SupportTicketResult|null>(null);const idempotencyKey=ref('');
const form=reactive({requesterName:'',requesterEmail:'',subject:'',description:''});

function newKey():string{return globalThis.crypto?.randomUUID?.()??`support-${Date.now()}-${Math.random().toString(36).slice(2,12)}`;}
async function loadStatus(){loadingStatus.value=true;error.value='';try{enabled.value=(await api.support.status()).enabled;}catch{enabled.value=false;error.value='无法读取支持服务状态，请稍后刷新。';}finally{loadingStatus.value=false;}}
async function submit(){if(submitting.value)return;submitting.value=true;error.value='';result.value=null;if(!idempotencyKey.value)idempotencyKey.value=newKey();try{result.value=await api.support.submit({...form},idempotencyKey.value);}catch(e){error.value=e instanceof Error?e.message:'支持请求提交失败，请稍后重试。';}finally{submitting.value=false;}}
function reset(){Object.assign(form,{requesterName:'',requesterEmail:'',subject:'',description:''});result.value=null;error.value='';idempotencyKey.value='';}
watch(()=>[form.requesterName,form.requesterEmail,form.subject,form.description],()=>{if(!submitting.value&&!result.value)idempotencyKey.value='';});
onMounted(loadStatus);
</script>

<template>
  <div class="support-view">
    <header class="support-header"><div><p class="eyebrow">INSTANCE SUPPORT</p><h1>获取支持</h1><p>由当前 nomops server 代为提交最小化支持请求。</p></div><button class="refresh" :disabled="loadingStatus" @click="loadStatus">刷新状态</button></header>
    <main class="support-content">
      <section class="boundary-card" aria-labelledby="support-boundary-title"><div class="boundary-icon">i</div><div><h2 id="support-boundary-title">发送范围清晰可控</h2><p>支持请求将发送到配置的 nomops-site。自动发送的元数据只有产品版本和部署模式。</p><strong>请勿提交密码、API Key、Token、凭证明文、工作流敏感数据或未经脱敏的日志。</strong></div></section>
      <div v-if="loadingStatus" class="state-card" role="status">正在检查支持服务配置…</div>
      <section v-else-if="!enabled" class="state-card unconfigured" data-test="support-disabled"><span>未配置</span><h2>管理员需要配置支持服务</h2><p>请在 nomops server 进程中同时设置 <code>NOMOPS_SUPPORT_URL</code> 与 <code>NOMOPS_SUPPORT_TOKEN</code>，然后重启服务。</p><p class="privacy">Token 只留在服务端，不会发送到浏览器或保存到 nomops 数据库。</p></section>
      <section v-else class="form-card">
        <div v-if="result" class="success" role="status" data-test="support-success"><span>✓</span><div><h2>支持请求已提交</h2><p>nomops-site 工单 ID</p><code>{{result.id}}</code><p class="created">创建时间：{{new Date(result.createdAt).toLocaleString()}}</p></div><button @click="reset">提交另一个问题</button></div>
        <form v-else aria-labelledby="support-form-title" @submit.prevent="submit">
          <div class="form-heading"><div><p class="eyebrow">SUPPORT REQUEST</p><h2 id="support-form-title">描述你遇到的问题</h2></div><span>所有字段均为必填</span></div>
          <div class="form-grid"><label for="support-name">姓名<input id="support-name" v-model="form.requesterName" data-test="support-name" required maxlength="100" autocomplete="name"></label><label for="support-email">邮箱<input id="support-email" v-model="form.requesterEmail" data-test="support-email" required maxlength="254" type="email" autocomplete="email"></label></div>
          <label for="support-subject">主题<input id="support-subject" v-model="form.subject" data-test="support-subject" required maxlength="200" placeholder="用一句话概括问题"></label>
          <label for="support-description">问题描述<textarea id="support-description" v-model="form.description" data-test="support-description" required minlength="10" maxlength="10000" rows="8" placeholder="说明期望行为、实际行为和已尝试的排查步骤；请先移除所有敏感信息。"></textarea></label>
          <p v-if="error" class="submit-error" role="alert" data-test="support-error">{{error}}</p>
          <div class="submit-row"><p>提交后，当前页面只会显示工单 ID；不会显示或接触实例支持 Token。</p><button class="submit" data-test="support-submit" :disabled="submitting">{{submitting?'正在安全提交…':'提交支持请求'}}</button></div>
        </form>
      </section>
    </main>
  </div>
</template>

<style scoped>
.support-view{min-height:100%;background:var(--color-background, #fff);color:var(--color-text, #242125)}.support-header{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;padding:32px clamp(22px,4vw,52px) 28px;border-bottom:1px solid var(--color-border,#e4e1e6)}.support-header h1{margin:3px 0 7px;font-size:30px;letter-spacing:-.8px}.support-header p{margin:0;color:var(--color-text-light,#6f6872)}.eyebrow{margin:0!important;color:#6950e8!important;font-size:10px!important;font-weight:750;letter-spacing:.14em}.refresh{border:1px solid var(--color-border,#dedbe1);border-radius:8px;background:transparent;padding:8px 12px}.support-content{display:grid;gap:18px;width:min(880px,calc(100% - 40px));margin:28px auto 52px}.boundary-card{display:grid;grid-template-columns:auto 1fr;gap:14px;padding:18px 20px;border:1px solid #ddd5ff;border-radius:12px;background:#f7f5ff}.boundary-icon{width:26px;height:26px;display:grid;place-items:center;border-radius:50%;background:#6950e8;color:white;font-weight:800}.boundary-card h2{margin:1px 0 6px;font-size:15px}.boundary-card p{margin:0 0 8px;color:#5f5865;line-height:1.6}.boundary-card strong{display:block;color:#9d3f45;font-size:13px;line-height:1.55}.state-card,.form-card{border:1px solid var(--color-border,#e1dde3);border-radius:14px;background:var(--color-card-background,#fff);box-shadow:0 10px 30px rgba(36,25,43,.05)}.state-card{padding:28px;color:#6f6872}.unconfigured span{display:inline-flex;padding:3px 9px;border-radius:99px;background:#f2e9cc;color:#775d12;font-size:11px;font-weight:700}.unconfigured h2{margin:14px 0 8px;color:var(--color-text,#242125)}.unconfigured p{line-height:1.65}.unconfigured code{overflow-wrap:anywhere}.unconfigured .privacy{font-size:12px}.form-card{padding:clamp(22px,4vw,34px)}.form-heading{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;margin-bottom:24px}.form-heading h2{margin:4px 0 0;font-size:21px}.form-heading>span{color:#817982;font-size:11px}.form-card form,.form-card label{display:grid;gap:8px}.form-card form{gap:18px}.form-card label{color:#5f5865;font-size:12px;font-weight:600}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.form-card input,.form-card textarea{width:100%;border:1px solid #d8d3da;border-radius:9px;background:var(--color-input-background,#fff);color:inherit;padding:11px 12px;font:inherit}.form-card textarea{resize:vertical;line-height:1.55}.form-card input:focus,.form-card textarea:focus{outline:2px solid #6950e8;outline-offset:1px;border-color:transparent}.submit-row{display:flex;justify-content:space-between;align-items:center;gap:22px;padding-top:4px}.submit-row p{max-width:480px;margin:0;color:#817982;font-size:11px;line-height:1.5}.submit{flex:0 0 auto;border:0;border-radius:9px;background:#6950e8;color:#fff;padding:11px 18px;font-weight:700}.submit:disabled{opacity:.58}.submit-error{margin:0;padding:10px 12px;border-radius:8px;background:#fff0f0;color:#a13f45;font-size:13px}.success{display:grid;grid-template-columns:auto 1fr auto;gap:16px;align-items:start}.success>span{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;background:#dff7e9;color:#137847;font-size:18px}.success h2{margin:3px 0 10px}.success p{margin:5px 0;color:#817982;font-size:12px}.success code{display:block;overflow-wrap:anywhere;color:#5140b8}.success button{border:1px solid #d8d3da;border-radius:8px;background:transparent;padding:8px 12px}.created{margin-top:10px!important}@media(max-width:640px){.support-header{padding:22px 20px}.support-header h1{font-size:25px}.support-header .refresh{display:none}.support-content{width:min(100% - 28px,880px);margin-top:18px}.boundary-card{padding:16px}.form-grid{grid-template-columns:1fr}.form-heading,.submit-row{align-items:stretch;flex-direction:column}.submit{width:100%}.success{grid-template-columns:auto 1fr}.success button{grid-column:1/-1;width:100%}}
</style>
